INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635580, 'Talk to Stan Goodman', 'Talk to Stan Goodman<BR><BR><font color="#63ad63">Identity Crisis:</font><BR>In order to leave Arete Landing and become a citizen of Rubi-Ka, you need an identity. Your mission is to create a fake ID Card to you can leave this place..<BR><BR>Alex told you to go talk to Stan Goodman, a local \'purveyer of recently used merchandise\'. He should be able to help with aquiring more parts for your ID card.<BR><BR><font color="#FF0000">Mission Objective:<BR>Talk to Stan Goodman.</font>', 2052536067, 244818, 0, 0, 6553, 0);
