INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635751, 'Take the contents of the Str...', 'Take the contents of the Strongbox <BR><BR>Stan told you to Pick the Lock on the Strongbox in the Merchant\'s Storage undetected. Now that you have bought a <a href=\'itemref://95577/95577/1\'>Lock Pick</a>, this should be an easy task.<BR><BR><font color="#FF0000">Mission Objective:<BR>Pick up (Left Click) your <a href=\'itemref://95577/95577/1\'>Lock Pick</a> from your inventory and drop it (Left Click) on the <a href=\'itemref://295604/295604/1\'>Merchant\'s Strongbox</a>.</font>', 2052536067, 244818, 0, 0, 6553, 0);
