INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635798, 'Hacking Skills', 'Hacking Skills<BR><BR>Vernon Godfray told you to hack the OT Technical Library to allow it to be worn by anyone.<BR><BR>Use the <a href=\'itemref://87810/87810/1\'>Hacker Tool</a> to hack the <a href=\'itemref://248377/248377/1\'> Omni-Tek Technical Library</a> to create the <a href=\'itemref://295756/295756/1\'>Hacked Technical Library</a>.<BR><a href=\'itemref://87810/87810/1\'><img src="rdb://99282"></a> + <a href=\'itemref://248377/248377/1\'><img src="rdb://130564"></a> = <a href=\'itemref://295756/295756/1\'><img src="rdb://130561"></a><BR><BR><font color="#FF0000">Mission Objective: Open the Tradeskill Kit %{KEY:WINDOW_TS}%, place the <a href=\'itemref://87810/87810/1\'>Hacker Tool</a> as the Source and the <a href=\'itemref://248377/248377/1\'> Omni-Tek Technical Library</a> as the Target, then press Build.</font>', 2052536067, 11340, 0, 0, 6553, 0);
