INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635805, 'Talk to Doctor Mason', 'Talk to Doctor Mason<BR><BR><font color="#63ad63">Identity Crisis:</font><BR>In order to leave Arete Landing and become a citizen of Rubi-Ka, you need an identity. Your mission is to create a fake ID Card to you can leave this place..<BR><BR>After helping Vernon, he gave you a Blank ICC ID Chip. He said that Dr Mason would be able to help you out further to imprint your DNA in to the chip.<BR><BR><font color="#FF0000">Mission Objective:<BR>Talk to Doctor Mason.</font>', 2052536072, 244818, 0, 0, 6553, 0);
