INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635806, 'Assemble an Implant (1/3)', 'Assemble an Implant (1/3)<BR><BR>Doctor Mason has provided you with the recipe for creating a <a href=\'itemref:// 113440/113441/1\'>Leg Implant: Agility, Shiny</a>. Once it has been completed, allow him to inspect it. <BR><BR><font color="#FFFFFF">1. Buy a <a href=\'itemref:// 101261/101262/1\'>A Basic Leg Implant</a> from the <a href=\'itemref:// 297320/ 297320/1\'>ICC Basic Implants</a> vending machine.<BR><BR>2. Buy a <a href=\'itemref://101781/101782/50\'>Agility Cluster - Shiny (Leg)</a> from the <a href=\'itemref:// 297323/ 297323/1\'>ICC Shiny Clusters</a> vending machine.<BR><BR>3. Insert the <a href=\'itemref://101781/101782/50\'>Agility Cluster - Shiny (Leg)</a> in to the <a href=\'itemref:// 101261/101262/5\'>A Basic Leg Implant</a> to create a <a href=\'itemref:// 113127/113128/5\'>Leg Implant: Agility, Shiny</a>.<BR><a href=\'itemref://101781/101782/50\'><img src="rdb://35985"></a> + <a href=\'itemref:// 101261/101262/5\'><img src="rdb://12688"></a> = <a href=\'itemref:// 113127/113128/5\'><img src="rdb://12689"></a><BR></font><BR><font color="#FF0000">Mission Objective: Open the Tradeskill Kit %{KEY:WINDOW_TS}%, place the <a href=\'itemref://101781/101782/50\'>Agility Cluster - Shiny (Leg)</a> as the Source and the <a href=\'itemref:// 101261/101262/5\'>A Basic Leg Implant</a> as the Target, then press Build.</font>', 2052536072, 11340, 0, 0, 6553, 0);
