INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635807, 'Assemble an Implant (2/3)', 'Assemble an Implant (2/3)<BR><BR>Doctor Mason has provided you with the recipe for creating a <a href=\'itemref:// 113440/113441/1\'> Leg Implant: Agility, Shiny</a>. Once it has been completed, allow him to inspect it. <BR><BR><font color="#FFFFFF">1. Buy a <a href=\'itemref://101785/101786/1\'>Stamina Cluster - Bright (Leg)</a> from the <a href=\'itemref://297322/297322/1\'>ICC Bright Clusters</a> vending machine. <BR><BR>2. Insert the <a href=\'itemref://101785/101786/1\'>Stamina Cluster - Bright (Leg)</a> in to the <a href=\'itemref:// 113127/113128/5\'>Leg Implant: Agility, Shiny</a> to create a <a href=\'itemref://113186/113187/5\'>Leg Implant: Agility, Shiny</a>.<BR><a href=\'itemref://101785/101786/50\'><img src="rdb://35984"></a> + <a href=\'itemref://113127/113128/5\'><img src="rdb://12689"></a>= <a href=\'itemref://113186/113187/5\'><img src="rdb://12689"></a><BR></font><BR><font color="#FF0000">Mission Objective: Open the Tradeskill Kit %{KEY:WINDOW_TS}%, place the <a href=\'itemref://101785/101786/1\'>Stamina Cluster - Bright (Leg)</a> as the Source and the <a href=\'itemref:// 113127/113128/5\'>Leg Implant: Agility, Shiny</a> as the Target, then press Build.</font>', 2052536072, 11340, 0, 0, 6553, 0);
