INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635816, 'Talk to Doctor Mason', 'Talk to Doctor Mason<BR><BR>Doctor Mason at the hospital is willing to help you assemble your ID chip, and imprint your DNA in to this vital component of your future identification card. <BR><BR><font color="#FF0000">Mission Objective:<BR>Give Dr Mason the following two items:<BR><BR><a href=\'itemref://296575/296575/1\'><img src="rdb://297387"></a><BR>A Blank ICC ID Chip<BR><a href=\'itemref://296574/296574/1\'><img src="rdb://297388"></a><BR>Some Biological Survey Nanobots', 2052536072, 244818, 1400, 2596, 6553, 0);
