INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635818, 'Talk to Lorelei', 'Talk to Lorelei<BR><BR><font color="#63ad63">Identity Crisis:</font><BR>In order to leave Arete Landing and become a citizen of Rubi-Ka, you need an identity. Your mission is to create a fake ID Card to you can leave this place..<BR><BR>You have been pointed towards a young woman named Lorelei, a bartender at one of the local watering holes. She apparently has quite the successful \'side business\', and should be able to help with creating your needed ID card.<BR><BR><font color="#FF0000">Mission Objective:<BR>Talk to Lorelei the Bartender.</font>', 2052536072, 244818, 0, 0, 6553, 0);
