INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635548, 'Terminate 5 Malfunctioning C...', 'Terminate 5 Malfunctioning Cleaning Robots<BR><br><font color="#63ad63">Identity Crisis:</font><BR>In order to leave Arete Landing and become a citizen of Rubi-Ka, you need an identity. Your mission is to create a fake ID Card to you can leave this place..<br><BR>Rex Larsson considers himself too lazy to clean up his cleaning business. Since you need his help, he wanted a favor in return. You have to terminate 5 of his Malfunctioning Cleaning Robots then open the package with brand new cleaning robots and set them to work.<BR><BR><font color="#FF0000">Mission Objective:<BR>Kill 5 Malfunctining Cleaning Robots.</font>', 2052536067, 11330, 0, 0, 6553, 0);
