INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635551, 'Open the Cargo Box', 'Open the Cargo Box<BR><BR>Rex Larsson considers himself too lazy to clean up his cleaning business. Since you need his help, he wanted a favor in return. You have to terminate 5 of his Malfunctioning Cleaning Robots then open the Cargo Box with brand new cleaning robots and set them to work.<BR><BR><font color="#FF0000">Mission Objective:<BR>Use (Right Click) the Cargo Box to open it.</font>', 2052536067, 244818, 0, 0, 6553, 0);
