INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635555, 'Talk to Marcus Stone', 'Talk to Marcus Stone<BR><BR><font color="#63ad63">Identity Crisis:</font><BR>In order to leave Arete Landing and become a citizen of Rubi-Ka, you need an identity. Your mission is to create a fake ID Card to you can leave this place..<BR><BR>Rex Larsson told you to spreak with Marcus Stone, an overseer for arriving cargo in the area, might be able to aid in getting your license issue settled.<BR><BR><font color="#FF0000">Mission Objective:<BR>Talk to Marcus Stone.</font>', 2052536067, 244818, 0, 0, 6553, 0);
INSERT INTO questobjectives (QuestId, Ordinal, ObjectiveType, Target, TargetLowId, TargetHighId, TargetQuality, Required) VALUES (1439635555, 0, 12, 'So, let me guess... You need some help with the fire?', 0, 0, 0, 1);
