INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635556, 'Extinguish the Gas Fire', 'Extinguish the Gas Fire<BR><BR>Marcus Stone mentioned that he may be able to assist you with your lack of identity on Rubi-Ka, but at a price. A recent accident on one of his landing pads has left cargo damaged and people injured. Bodies can heal while cargo cannot. Extinguish one of the Gas Fires that has errupted on the landing pad.<BR><BR><font color="#FF0000">Mission Objective:<BR>(Left Click) the <a href=\'itemref://296780/296780/1\'>Compact Fire Suppressant Container</a> in your inventory to lift it up, then Left Click the Gas Fire to apply the fire suppressant.</font>', 2052536067, 244818, 0, 0, 6553, 0);
