INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635562, 'Return to Marcus', 'Return to Marcus<BR><BR>After extinguishing one of the Gas Fires on Marcus\' landing platform, he may be more willing to help you with your lack of identity.<BR><BR><font color="#FF0000">Mission Objective:<BR>Talk to Marcus Stone and hand him the <a href=\'itemref://296780/296780/1\'>Compact Fire Suppressant Container</a>.</font>', 2052536067, 158429, 1080, 1281, 6553, 0);
