INSERT INTO questobjectives (QuestId, Ordinal, ObjectiveType, Target, TargetLowId, TargetHighId, TargetQuality, Required) VALUES (1439635563, 0, 12, 'What hardware does she need and where could I find it?', 0, 0, 0, 1);
