INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635578, 'Report to Alex', 'Report to Alex<BR><BR>You have put a major dent in Demond Caltiri\'s plans. Since Bill doesn\'t want to talk to you about this matter, you decided to update Alex on your progress. She did promise you a reward for your efforts...<BR><BR><font color="#FF0000">Mission Objective:<BR>Talk to Alex Gibbs.</font>', 2052536067, 244818, 1200, 2229, 6553, 0);
INSERT INTO questobjectives (QuestId, Ordinal, ObjectiveType, Target, TargetLowId, TargetHighId, TargetQuality, Required) VALUES (1439635578, 0, 12, 'I don\'t think you will need to worry about Calitri any longer.', 0, 0, 0, 1);
