INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1439635717, 'Tradeskilling (1/4): Assembl...', 'Tradeskilling (1/4): Assemble a Nano Sensor<BR><BR><font color="#FF0000">WARNING: If you are interested in learning tradeskilling, this mission will help you learn the basics. However, only Engineers and Traders are equipped with profession tools to help them master the art of tradeskilling.</font><BR><BR>Alex Gibbs has provided you with the recipe for creating a <a href=\'itemref:// 156026/156027/1\'>Personalized Basic Robot Brain</a>. Once this mission has been completed, allow her to inspect it. <BR><BR><font color="#FFFFFF">1. Buy the following item from the <a href=\'itemref://297281/297281/1\'>Junk Shop</a>:<BR><a href=\'itemref://150922/150922/1\'><img src="rdb://151011"> Screwdriver</a><BR><BR>2. Find <a href=\'itemref://42620/42620/1\'>Robot Junk</a>.<BR>Do so by killing and looting a robot.<BR><BR>3. Modify the <a href=\'itemref://42620/42620/1\'>Robot Junk</a> with the <a href=\'itemref://150922/150922/1\'>Screwdriver</a> to create a <a href=\'itemref://150923/150924/1\'>Nano Sensor</a>.<BR><a href=\'itemref://150922/150922/1\'><img src="rdb://151011"></a> + <a href=\'itemref://42620/42620/1\'><img src="rdb://290417"></a> = <a href=\'itemref://150923/150923/1\'><img src="rdb://149940"></a><BR></font><BR><font color="#FF0000">Mission Objective: Open the Tradeskill Kit %{KEY:WINDOW_TS}%, place the <a href=\'itemref://150922/150922/1\'>Screwdriver</a> as the Source and the <a href=\'itemref://42620/42620/1\'>Robot Junk</a> as the Target, then press Build.</font>', 2052536065, 11340, 0, 0, 6553, 0);
