INSERT INTO quests (Id, Name, Description, GiverId, IconId, CashReward, ExperienceReward, Playfield, Requires) VALUES (1440330011, 'Use the Stim on a Wounded Do...', 'Use the Stim on a Wounded Dockworker<BR><BR>Marcus Stone\'s workers got damaged by the fire, he asked you to help him save their lives.<BR><BR> <font color="#FF0000">Mission Objective:<BR>Target a Wounded Dockworker and use the <a href=\'itemref://297044/297044/1\'>Health Regeneration Stim</a> (Right-Click).</font>', 2052536066, 244818, 0, 0, 6553, 0);
