INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 11, 0, 0, 'Thank you, Mixia.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 12, 0, 0, 'It is quite simple, really. All you need to find is some \'Robot Junk\' the rest can be bought from my Junk Shop. You can loot \'Robot Junk\' from robot remains. Just kill a robot and you might have a chance of salvaging its parts. The higher quality \'Robot Junk\', the better \'Personalized Robot Brain\' you will make. I will upload the recipe for making a \'Personalized Robot Brain\' to your ncu.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 1, 0, 0, 'Hello there, what do you want?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 1, 1, 1, 'I was told to bring you this device so you could help me get an ID.', 0, 2, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 1, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 2, 0, 0, 'Wait.. You came onto Rubi-Ka without sufficient identification? What? I don\'t even... I need a moment to think... I am only experienced with providing identification to newly created automations. While the process is similar in nature, I can only provide you with the most basic identification board.\\n\\nTo imprint that with an actual identification that would be recognized by ICC, you would need to go elsewhere. I can help you with part of the process though... if you\'re willing to potentially give me a hand.. \\n\\nLet me see what you have for me...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 2, 1, 3, 'Drag and drop the item(s) you want to give to Alex Gibbs into one of the slots available and press "accept"', 1, 3, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 3, 0, 0, 'It\'s only part of a broken robot and I already have this one.. Ah well, you have to do me a favour if I\'m going to help you further with your ID problem. Have you heard of Desmond Calitri? He is the administrator who operates and oversees all the operations around this industrial area of Arete Landing and has been starting to cut budgets for my engineering work. I want you to find out why, simply remotely hack into one of his patrolling security droids, and then plant an audio recording device in his office.\\n\\nOnce you\'re done, talk to old Bill. He\'s the closest contact I have with the ICC officials. He is usually down at the Bronto Dog Kiosk this time of the day.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 3, 1, 1, 'I will get it done.', 0, 11, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 3, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 4, 0, 0, 'Whats up?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 4, 1, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 0, 0, 'Sure, what do you want to know?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 1, 1, 'Who are you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 2, 1, 'What do you do around here?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 3, 1, 'Have you been working here for a while?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 4, 1, 'What goes on here?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 5, 1, 'Who is in charge around here?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 5, 6, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 6, 0, 0, 'Whats up?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 6, 1, 1, 'I don\'t think you will need to worry about Calitri any longer.', 0, 10, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 6, 2, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 6, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 7, 0, 0, 'Smiling brightly Alex squeals a bit, perhaps a little bit <i>too</i> happy to hear the tales of your sabotage and murder.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 8, 0, 0, 'Fantastic! Here, take this encryption compiler - Without (A) something to encrypt, and (B) some encryption <i>codes</i> it\'s fairly worthless... but if you can get your hands on a proper ID chip <i>and</i> some authentic ICC security codes... Talk to Stan Goodman, a local merchant, he might be able to help you out with the next step in the process.\\n\\nOh, if you need any help crafting items, I\'m here to help you!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 8, 1, 1, 'Can you tell me how to make a Personalized Robot Brain?', 0, 12, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 8, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 9, 0, 0, 'Thank you, Kaleno.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 9, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 10, 0, 0, 'Smiling brightly Alex squeals a bit, perhaps a little bit <i>too</i> happy to hear the tales of your sabotage and murder.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 10, 1, 0, 'Fantastic! Here, take this encryption compiler - Without (A) something to encrypt, and (B) some encryption <i>codes</i> it\'s fairly worthless... but if you can get your hands on a proper ID chip <i>and</i> some authentic ICC security codes... Talk to Stan Goodman, a local merchant, he might be able to help you out with the next step in the process.\\n\\nOh, if you need any help crafting items, I\'m here to help you!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 10, 2, 1, 'Can you tell me how to make a Personalized Robot Brain?', 0, 12, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', 10, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Alex Gibbs', -1, 0, 0, 'Be careful out there. Remember: robots don\'t kill, but bad programming does!', 0, 0, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Alex Gibbs', 110, '1439635570', '', '', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Alex Gibbs', 110, '1439635570', '', '', 2);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Alex Gibbs', 100, '', '', '', 4);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Alex Gibbs', 110, '1439635578', '', '', 6);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 16, 0, 0, 'Sounds good. I\'ll be here.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 1, 0, 0, 'Good day to you! If you\'ve come looking to improve your quality of life through the power of bodily augmentation, you have come to the right place.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 2, 0, 1, 'I heard you might be able to help me...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 2, 1, 1, 'I have some questions...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 2, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 3, 0, 0, 'You spend a few moments explaining your situation to the patient doctor.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 3, 1, 0, 'Ah, yes, another one. I should say that forging an ID chip is rather illegal and somewhat risky... but truthfully I\'d rather lend a hand against the bureaucratic red-tape-nonsense than be a stickler for the law. \\n\\nHowever, I won\'t help you without a little hand in return. Trust me, the task I have for you is mutually beneficial.. ', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 4, 0, 0, 'See my fine selection of vending machines? ICC wants me to make more money, and that is where you come in. Assemble a Leg Implant: Agility, Shiny, I will upload the recipe to your ncu. Show it to me when you are done.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 4, 1, 1, 'I\'ll come back when I\'m done.', 0, 16, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 5, 0, 0, 'Welcome back, I hope you were successful.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 5, 1, 1, 'I finished that implant.', 0, 15, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 5, 2, 1, 'I have some questions...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 5, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 6, 0, 0, 'Good, let\'s see how you did. Please give it to me.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 7, 0, 3, 'Drag and drop the item(s) you want to give to Dr. Mason into one of the slots available and press "accept"', 1, 8, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 8, 0, 0, 'Not bad for a beginner. Now, I think you should install it. Use the Surgery Clinic in the corner.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 8, 1, 1, 'How do I install an Implant?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 8, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 9, 0, 0, 'Welcome back, I hope you were successful.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 9, 1, 1, 'I have installed the implant and I have all the items we need for the chip.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 9, 2, 1, 'I have some questions...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 9, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 10, 0, 0, 'The good doctor clasps his hands together with a big smile, nodding to himself.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 11, 0, 0, 'Excellent, then let\'s get started. I\'ll need the Blank ICC ID Chip and the Biological Survey Nanobots, if you please.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 11, 1, 3, 'Drag and drop the item(s) you want to give to Dr. Mason into one of the slots available and press "accept"', 2, 12, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 12, 0, 0, 'Without any warning he pokes the side of your neck with the DNA-Unlocking device. A little droplet of blood runs down the outside of your throat.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 12, 1, 0, 'And... there we have it, one personalized ID chip, ready to be used in a card. \\nLorelei down at the bar has a... slight side business. Speak with her, and she should be able to help out with the final step.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 12, 2, 1, 'Thank you for all the help.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 12, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 13, 0, 0, 'Sounds good. I\'ll be here.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 14, 0, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 15, 0, 0, 'Good, let\'s see how you did. Please give it to me.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Dr. Mason', 15, 1, 3, 'Drag and drop the item(s) you want to give to Dr. Mason into one of the slots available and press "accept"', 1, 8, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Dr. Mason', 110, '1439635805', '', '', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Dr. Mason', 110, '1439635805', '', '', 2);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Dr. Mason', 110, '1439635809', '', '', 5);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Dr. Mason', 110, '1439635809', '', '', 6);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Dr. Mason', 110, '1439635816', '', '', 9);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 5, 0, 0, 'Always with the questions...good workers used to just do what they were told.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 5, 1, 0, 'Flint sighs.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 5, 2, 0, '\\nThese gizmos works like brains for my robots. Originally, they were programmed to seek out and chase away any living creatures that wandered in, but now they all just move around aimlessly. That said they\'re a fairly generic part, good for all sorts of things. Alex gets me to procure one for her once in a while, for.... various reasons. Seems these little toys can be used for the construction of other things too.\\n\\nSo... be a pal and get this handled for me, won\'t you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 6, 0, 0, 'Hey, be careful what you call "scrap" around here. That\'s MY scrap you\'re talkin\' about.\\n\\nAnyway, you\'ll just have to ask her. That\'s knowledge that I don\'t need to know or want to know. The less I know about her and her personal projects, the better.\\n\\nAnyway, it doesn\'t matter to you why she wants one - All that matters to you is that she does. Whatever you came here for, she should be able to help; Alex\'s a bit of a whiz. If you want more information on what she\'s going to do with it, ask her yourself. I\'m staying out of it.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 1, 0, 0, 'It\'s amazing how much trash finds itself on this planet. Hey, don\'t look at me like that, I was talking about the filth behind me.\\n\\nMy name is Flint. I look after the junkyard.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 1, 1, 1, 'Hi Flint, I\'m Mixia. I was told you had work for me.', 0, 2, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 1, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 2, 0, 0, 'Nobody talks to me, the junkyard guy, unless they need something very specific, and usually something done off of the record. Funny how often these requests have been made recently...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 2, 1, 0, 'Flint takes a deep breath before continuing, shaking his head as though to clear the thoughts.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 2, 2, 0, 'Anyway, yes, first things first. I have a friend, yes, I\'ll call her a <i>friend</i> and she needs a small piece of hardware and... well, I <i>could</i> go do it myself, but...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 2, 3, 1, 'What hardware does she need and where could I find it?', 0, 3, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 2, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 3, 0, 0, 'You are a quick one, aren\'t you. Go out back to the \'yard and take out some of the old rickety robots back there. The device Alex needs is called a Bio Analyzing Computer. Destroy a few robots and you will find it. Don\'t bother coming back to me with it, give it to Alex directly.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 3, 1, 1, 'What is a "Bio Analyzing Computer?"', 0, 5, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 3, 2, 1, 'What does this Alex person want with a piece of robot scrap?', 0, 6, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 3, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 4, 0, 0, 'It\'s amazing how much trash finds itself on this planet. Hey, don\'t look at me like that, I was talking about the filth behind me.\\n\\nMy name is Flint. I look after the junkyard.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 4, 1, 1, 'Hi Flint, I\'m Kaleno. I was told you had work for me.', 0, 2, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Flint Novak', -1, 0, 0, 'Good luck out there!', 0, 0, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Flint Novak', 110, '1439635563', '', '', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Flint Novak', 110, '1439635563', '', '', 4);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 6, 0, 0, 'By yourself? That sounds dangerous.. Well, In that case you should take care of that guy he was talking to, "Alfonzo Rizzolo."\\n\\nOh and by the way, I don\'t know you and I have not heard anything about these plans. Don\'t talk to me again, got it?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 1, 0, 0, 'There have been a number of accidents in my shuttleport recently. I am told they are just that, accidents. I have lived here long enough to know that there are no accidents on this planet. These are actions of terrorists...some probably aren\'t even documented citizens.\\n\\nSpeaking of which, who are you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 2, 0, 1, 'Alex Gibbs thought you may be interested in seeing this?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 2, 1, 1, 'My name is Mixia. I am new to the planet.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 2, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 3, 0, 0, 'Oh, please, the SecTec Monitor! Give it here at once! I have been waiting for this to arrive.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 3, 1, 3, 'Drag and drop the item(s) you want to give to ICC Immigration Officer Bill into one of the slots available and press "accept"', 1, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 4, 0, 0, 'This is just what she promised...oh wait...I am hearing something from Calitri\'s office.\\n\\nIt seems he wants to arrange an "accident" to befall one of the head workers, Cedric Harding. This is awful! I...I don\'t know what to do! I can\'t move forces, and by the time I find a superior officer, it could be all over.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 4, 1, 1, 'I will take care of it.', 0, 6, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 5, 0, 1, 'Alex Gibbs thought you may be interested in seeing this?', 0, 3, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 5, 1, 1, 'My name is Kaleno. I am new to the planet.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', 5, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'ICC Immigration Officer Bill', -1, 0, 0, 'Take care of yourself.', 0, 0, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'ICC Immigration Officer Bill', 110, '1439635576', '', '', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'ICC Immigration Officer Bill', 110, '1439635576', '', '', 2);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'ICC Immigration Officer Bill', 110, '1439635576', '', '', 5);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 1, 0, 0, 'What are you lookin\' at? I am conducting some delicate business that needs my attention.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 1, 1, 1, 'I have come to put your plans to an end.', 0, 2, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 1, 2, 1, 'I am looking for work.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 1, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 2, 0, 0, 'What did you just say, little leet?\\n\\n', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 2, 1, 0, 'I ain\'t afraid of you, take your best shot. I\'ll use you as a warmup before I pay someone a visit.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 2, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Kneebreaker Alfonzo Rizzolo', 100, '', '', '', 1);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 1, 0, 0, 'Lolly wants a cracker!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 1, 1, 1, 'Please get in to the cage...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 1, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 2, 0, 0, 'U giev cracker! Nao!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 2, 1, 3, 'Drag and drop the item(s) you want to give to Lolly the Reet into one of the slots available and press "accept"', 1, 3, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 3, 0, 0, 'The bird starts eating the tasty cookie. It is distracted, now is the time to catch it!', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 3, 1, 1, '(Quietly pick up the bird)', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 3, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 4, 0, 0, 'Lolly doesn\'t notice that you get closer and by the time he does, he is already in your hands!', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 5, 0, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 6, 0, 0, 'U giev cracker! Nao!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lolly the Reet', 7, 0, 3, 'Drag and drop the item(s) you want to give to Lolly the Reet into one of the slots available and press "accept"', 1, 3, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Lolly the Reet', 100, '', '', '', 1);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 20, 0, 0, 'Raising an eyebrow she looks slightly confused for a moment.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 20, 1, 0, 'Its a bird! Have you been living under a rock?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 21, 0, 0, 'No, thank you. I\'m glad to have Lolly back!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 21, 1, 0, 'She looks down at the cage...', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 21, 2, 0, 'Excuse me... I have some feathers to pick with my little friend...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 1, 0, 0, 'The young woman before you smiles brightly as you approach, her hands busy polishing a tumbler with a rather less-than-sanitary looking rag.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 1, 1, 0, 'Hey there, cutie. What can I get ya?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 1, 2, 1, 'I was told you might be able to give me a hand...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 1, 3, 1, 'What do you have?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 1, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 2, 0, 0, 'You yet again start the process of explaining your situation when, barely five words in, Lorelei raises her hand to stop you with a soft, friendly chuckle.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 2, 1, 0, 'No, no, it\'s ok I can help you! You don\'t have to go through the whole story. Probably better I <i>don\'t</i> know. However, I will need you to do me a favor before I help you out.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 3, 0, 1, 'I will help you, what do you need?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 3, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 4, 0, 0, 'You need to find my stupid Reet, Lolly. He escaped again... I believe he might have found a girlfriend or something... Try looking for him near the other Reets in the desert oasis.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 5, 0, 1, 'What is a Reet?', 0, 20, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 5, 1, 1, 'Is there anything in particular I should know about Lolly?', 0, 17, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 5, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 6, 0, 0, 'The young woman before you smiles brightly as you approach, her hands busy polishing a tumbler with a rather less-than-sanitary looking rag.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 6, 1, 0, 'Hey there, cutie. What can I get ya?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 6, 2, 1, 'I have the bird...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 6, 3, 1, 'What do you have?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 6, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 7, 0, 0, 'With a sharp smile and nod the bartender extends her hand.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 8, 0, 0, 'Alright then, sounds like we\'re ready to do this. I\'ll need the ID chip too.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 8, 1, 3, 'Drag and drop the item(s) you want to give to Lorelei the Bartender into one of the slots available and press "accept"', 2, 9, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 9, 0, 0, 'She places the bird cage on the ground and you can see Lolly breaking out of his cage as she crouches down behind the counter.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 9, 1, 0, 'This\'ll take just a sec.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 9, 2, 0, 'You hear a few miscellaneous beeps and dings from... something... underneath the bar top.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 9, 3, 0, ' And here you go. Congratulations, you are now a fully-fledged colonist of Rubi-Ka!\\nYou should talk to Vaughn Hammond about entering ICC HQ.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 9, 4, 1, 'Thank you.', 0, 21, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 9, 5, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 10, 0, 0, 'The young woman before you smiles brightly as you approach, her hands busy polishing a tumbler with a rather less-than-sanitary looking rag.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 10, 1, 0, 'Hey there, cutie. What can I get ya?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 10, 2, 1, 'What do you have?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 10, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 11, 0, 0, 'With a sharp smile and nod the bartender extends her hand.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 11, 1, 0, 'Alright then, sounds like we\'re ready to do this. I\'ll need the ID chip too.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 12, 0, 3, 'Drag and drop the item(s) you want to give to Lorelei the Bartender into one of the slots available and press "accept"', 2, 9, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 13, 0, 0, 'The young woman before you smiles brightly as you approach, her hands busy polishing a tumbler with a rather less-than-sanitary looking rag.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 14, 0, 0, 'Hey there, cutie. What can I get ya?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 14, 1, 1, 'I was told you might be able to give me a hand...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 14, 2, 1, 'What do you have?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 14, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 15, 0, 0, 'You yet again start the process of explaining your situation when, barely five words in, Lorelei raises her hand to stop you with a soft, friendly chuckle.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 16, 0, 0, 'No, no, it\'s ok I can help you! You don\'t have to go through the whole story. Probably better I <i>don\'t</i> know. However, I will need you to do me a favor before I help you out.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 16, 1, 1, 'I will help you, what do you need?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 16, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 17, 0, 0, 'He is blue and talks a lot... \\nAnd he really loves peanut butter cookies. If you plan to lure him in to the cage, it would probably be a good idea to buy a cookie before you leave.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 18, 0, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 19, 0, 0, 'With a sharp smile and nod the bartender extends her hand.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 19, 1, 0, 'Alright then, sounds like we\'re ready to do this. I\'ll need the ID chip too.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Lorelei the Bartender', 19, 2, 3, 'Drag and drop the item(s) you want to give to Lorelei the Bartender into one of the slots available and press "accept"', 2, 9, 0, 0);
