INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marco Spida', 1, 0, 0, 'Do you need any Nano Programs? I\'m the guy.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marco Spida', 2, 0, 1, 'What can you tell me about Nano Programs?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marco Spida', 2, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marco Spida', -1, 0, 0, 'Bye!', 0, 0, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marco Spida', 100, '', '', '', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marco Spida', 100, '', '', '', 2);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 13, 0, 0, 'Where are you? Are you being serious? You\'re on the planet Rubi-Ka. She may not look like much, but deep down, she\'s full of some precious materials that people are killing to get. Literally.\\n\\nRight now we\'re in the primary ICC Shuttleport on the planet, right next to their main establishment. Assuming you have a valid ID card, that\'s where you\'re going to want to head - After you\'re in there and done with all the processing, you\'ll be able to go... where-ever you\'d like to go, I guess.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 14, 0, 0, 'Marcus Stone. I mostly oversee the unloading of cargo that finds its way up here on this little orange rock we all call "home". I don\'t know where all of you are coming from, but there\'s sure been a lot of folks walking out of these freighters.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 15, 0, 0, 'A little smirk crosses his lips as he nods his approval.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 15, 1, 0, 'Yeah, now you\'re catching on. As you have already noticed, a few, small fires have erupted up on this landing platform. The appropriate authorities are on their way to deal with the wounded and property damage, but if you wouldn\'t mind helping me with a few of these fires, it would be appreciated. You do that, I\'ll see if I can\'t help you out with your little... identity issue.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 16, 0, 0, 'Good luck out there, kid.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 1, 0, 0, 'As you might have noticed, I\'m a little busy at the moment.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 1, 1, 1, 'Actually, Rex said you could help me... I seem to have misplaced my Identity Card.', 0, 2, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 1, 2, 1, 'Who are you?', 0, 14, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 1, 3, 1, 'Where am I?', 0, 13, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 1, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 2, 0, 0, 'Well now. Sounds like you got a problem. I\'m not going to say I <i>can\'t</i> help you but, well, as you\'ll find out soon enough, everyone on Rubi-Ka needs <i>something</i>..', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 2, 1, 1, 'So, let me guess... You need some help with the fire?', 0, 15, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 2, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 3, 0, 0, 'You did a pretty good job there!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 3, 1, 1, 'Thanks.', 0, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 3, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 4, 0, 0, 'Hand me the Compact Fire Suppressant Container, please.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 4, 1, 3, 'Drag and drop the item(s) you want to give to Marcus Stone into one of the slots available and press "accept"', 1, 5, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 5, 0, 0, 'And, good to my word.... ', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 5, 1, 0, 'Reaching into a small pouch by his side he produces a thin, flat, metallic disc, barely larger than a fingernail.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 5, 2, 0, 'There. That\'s a generic nano transmitter, pretty standard equipment for... well, most everything. Same gizmo that lets you see things like data and information via your NCU\'s heads-up-display. Most of \'em are already programmed with something or another - Manufacturer\'s information, warning notes, care & use & feeding or whatever of whatever it is you\'re looking at. Typically blank ones aren\'t issued to the public - Supposed to make \'em hard to fake... Now, you go talk to Flint Novak. He runs the junkyard. Just head on down for the bottom of the ramp and look for a little shack. Can\'t miss it.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 5, 3, 1, 'Thanks again.', 0, 6, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 5, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 6, 0, 0, 'Was there anything else?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 6, 1, 1, 'Who are you?', 0, 14, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 6, 2, 1, 'Where am I?', 0, 13, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 6, 3, 1, 'Are those wounded workers your guys?', 0, 7, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 6, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 7, 0, 0, 'They are.. Say, if you are not in a hurry would you mind saving at least one of them? I\'ll reward you with some equipment to patch yourself up when you get hurt.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 7, 1, 1, 'I\'ll do it, just tell me how.', 0, 8, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 7, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 8, 0, 0, 'Take this Health Regeneration Stim and use it on one of my wounded workers.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 8, 1, 2, 'Use the Stim on a Wounded Do...', 0, 0, 0, 1440330011);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 8, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 9, 0, 0, 'What?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 9, 1, 1, 'I healed one of your workers with the Health Regeneration Stim.', 0, 10, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 9, 2, 1, 'Who are you?', 0, 14, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 9, 3, 1, 'Where am I?', 0, 13, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 9, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 10, 0, 0, 'Great, hand me the stim.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 10, 1, 3, 'Drag and drop the item(s) you want to give to Marcus Stone into one of the slots available and press "accept"', 1, 11, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 11, 0, 0, 'Thank you for saving one of my workers. Here, take this first aid equipment to heal yourself when you need it.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 11, 1, 1, 'You are welcome.', 0, 16, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 11, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 12, 0, 0, 'Take this Health Regeneration Stim and use it on one of my wounded workers.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', 12, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Marcus Stone', -1, 0, 0, 'Yep, off you go.', 0, 0, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marcus Stone', 110, '1439635555', '', '', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marcus Stone', 110, '1439635562', '', '', 3);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marcus Stone', 110, '1439635562', '', '1440330011', 3);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marcus Stone', 110, '1440330014', '', '', 9);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marcus Stone', 60, '1440330011', '', '', 12);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Marcus Stone', 90, '', '1439635562', '1440330011', 6);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 11, 0, 0, 'Off you go, I need to relax now. It has been a long day at work.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 12, 0, 0, 'The man taps his foot impatiently.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 12, 1, 0, ' Well? I\'m still waiting.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 1, 0, 0, 'Hi, I\'m Rex. \\nNice moves, I\'m impressed. It is not easy hiding in a cargo ship. Say, how did you do it?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 1, 1, 1, 'I don\'t really feel like telling you any of my secrets. If you\'ll excuse me, I need to go now.', 0, 2, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 1, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 2, 0, 0, 'You have it all figured out, don\'t you? I bet you forgot that you need an ID card to enter ICC. I don\'t even need glasses to notice that you don\'t have anything of value...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 2, 1, 0, 'Rex lowers his voice.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 2, 2, 0, 'You know, I arrived here the same way as you just did. I might know a guy that can help you out... I got a fake ID myself.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 2, 3, 1, 'Who said I don\'t have any ID?', 0, 3, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 2, 4, 1, 'Tell me who to talk to.', 0, 9, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 2, 5, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 3, 0, 0, 'Alright there, boss, say what you want. Just know that if you don\'t have any form of identification, your options are limited. You can either take a quick stroll \\n\\nOr.. you could get my help getting an ID, if you start helping me out here instead of denying facts...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 3, 1, 1, 'Get to the point, Rex.', 0, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 3, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 4, 0, 0, 'Ya see these Cleaning Robots? They are old, stupid and broken now. I need you to terminate them and open the cargo box with the new ones so they can start cleaning up this place... It looks messy here, don\'t you agree?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 4, 1, 1, 'I\'ll do it if you promise to tell me who your contact is.', 0, 5, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 5, 0, 0, 'Excellent choice, I will tell you what you need to know when you have completed the task.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 5, 1, 2, 'Terminate 5 Malfunctioning C...', 0, 0, 0, 1439635548);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 5, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 6, 0, 0, 'How did it go?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 6, 1, 1, 'I\'ve done what you asked. Can you tell me who your contact is?', 0, 7, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 6, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 7, 0, 0, 'I\'ve had my fun watching you do my job. You didn\'t actually believe that I got a fake ID from someone here, did you? The only person I know around here is Marcus Stone, you could try asking him.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 7, 1, 1, 'I can see why you don\'t have too many friends.', 0, 11, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 7, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 8, 0, 0, 'It is not that difficult, just slap the robots and open the cargo box.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 8, 1, 1, 'Certainly! Just let me get right on that...', 0, 12, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 8, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 9, 0, 0, 'I\'ve got nothing to say to you, unless you\'re willing to help me take care of something.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 9, 1, 0, 'Rex grins.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 9, 2, 1, 'Get to the point, Rex.', 0, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 9, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 10, 0, 0, 'Excellent choice, I will tell you what you need to know when you have completed the task.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', 10, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', -1, 0, 0, 'He sighs, shaking his head.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Rex Larsson', -1, 1, 0, ' How do so many people keep ending up in these cargo shuttles...?', 0, 0, 0, 0);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Rex Larsson', 100, '', '', '1439635548', 1);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Rex Larsson', 110, '1439635555', '', '', 6);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Rex Larsson', 110, '1439635551', '', '', 8);
INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Rex Larsson', 60, '1439635548', '', '', 10);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 14, 0, 0, 'I offer several types of armor, some which aren\'t too common, and some which you won\'t find anywhere else. Come check out my wares.\\n\\n<font color="#ff0000">Press the Shopping Cart icon towards the bottom of the chat window to engage trade with Sarah.</font>', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 15, 0, 0, 'Good luck out there.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 1, 0, 0, 'Well howdy, y\'all. Welcome and step on up to Sarah Greene\'s Armor Imporium. As a new arrival you may not know that it\'s dangerous to go alone through the wilds of Rubi-Ka, without proper protection. Lucky for you, I\'ve got the best custom-made protection available in the shuttleport!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 1, 1, 1, 'I heard that we might be able to help each other out...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 1, 2, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 1, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 2, 0, 0, 'You spend a few moments explaining your basic plight, making sure to avoid mentioning Stan\'s name.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 3, 0, 0, 'I can help ya out. You got good timin\' too, just came up on my own little crisis. Somebody done made off with one of my prototype suits I was workin\' on. Ain\'t much they can <i>do</i> with it, bein\' DNA-locked to me and all, but it\'s still a pretty significant amount of effort and time from my end that went into it so I ain\'t quite ready to just let it go that easy. You get this back for me and I\'ll see what I can do about helping with your own issues.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 3, 1, 1, 'Have you tried to contact ICC?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 3, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 4, 0, 0, 'Sarah\'s eyes roll as she scoffs, head shaking side to side with unhidden disdain.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 5, 0, 0, 'That ain\'t gonna do me no good. Local patrols don\'t exactly have the best record of catchin\' thieves; tell the truth I can\'t think of a single time that one of us vendors got ripped off and we got our stuff back, regardless of affiliation or standin\'. Guess it just all comes with the territory.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 5, 1, 1, 'What do you have for sale?', 0, 14, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 5, 2, 1, 'Do you know anyone I should talk to around here?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 5, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 6, 0, 0, 'You should talk to Remi Gallois. He ain\'t such a bad guy.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 6, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 7, 0, 0, 'Well howdy, y\'all. Welcome and step on up to Sarah Greene\'s Armor Imporium. As a new arrival you may not know that it\'s dangerous to go alone through the wilds of Rubi-Ka, without proper protection. Lucky for you, I\'ve got the best custom-made protection available in the shuttleport!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 7, 1, 1, 'I found the stolen armor.', 0, 8, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 7, 2, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 7, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 8, 0, 0, 'Sarah claps her hands happily, beaming as you produce the stolen suit.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 8, 1, 0, ' And you actually even brought it back! Well hot damn. If you don\'t mind passin\' it over...?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 8, 2, 3, 'Drag and drop the item(s) you want to give to Sarah Greene into one of the slots available and press "accept"', 1, 9, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 9, 0, 0, 'Yeeehaw, y\' found it! I was startin\' to think it was lost an\' gone forever. I\'m so happy I could kiss ya! But I won\'t, \'cause that\'s a little creepy.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 9, 1, 0, 'With a small \'thud\' she tosses a package onto the counter in front of you, heavy and thick.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 9, 2, 0, 'There ya go, a deal is a deal.\\nI\'m sure Vernon Godfray should be able to help with aquiring more parts needed for your ID card.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 9, 3, 1, 'Thanks.', 0, 15, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', 9, 4, 1, 'Goodbye', 0, 0, 2, 0);
