INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Sarah Greene', -1, 0, 0, 'Come back some time n\' check out my wares.', 0, 0, 0, 0);
