INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 6, 4, 0, '\\n\\nNew data delay point has been specified. No notification messages have been sent.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 1, 0, 0, 'Please choose an operation:\\n* Register a new/completed shipment\\n* Cancel an existing shipment\\n* Access Shipping Manifest Logging', 0, 0, 0, 0);
