INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 3, 0, 0, 'Please Enter Password.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 3, 1, 3, 'Drag and drop the item(s) you want to give to Shipping Manifest Terminal into one of the slots available and press "accept"', 1, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 4, 0, 0, 'Password Correct. Access Granted.\\n\\nShipping Manifest Logs are maintained within ICC Headquarters. To view Log History, please schedule an appointment with Roy K. of Shuttleport Administration.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 4, 1, 1, '(Re-route shipping report data.)', 0, 6, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Shipping Manifest Terminal', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
