INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 16, 0, 0, 'No, no you don\'t. Now, I\'ll be uploading the target\'s location to your NCU.\\n\\nThe work itself is relatively simple:\\n1: Buy a lockpick.\\n2: Sneak into the small building undetected. Locate the strongbox your NCU directs you toward and clean it out. Inside you\'ll find an Adaptation Factory.\\n3: Once you\'ve procurred this item, return to me and we\'ll see about creating your unique ID chip.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 1, 0, 0, 'Hello there, stranger.\\n\\nThe name is Stan, and I am a man who likes to deal in previously-owned merchandise.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 1, 1, 1, 'I heard you could help me out... So, do you have any work for me?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 1, 2, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 1, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 2, 0, 0, 'My my... Aren\'t we eager? Ambition is something that is dreadfully lacking from new colonists, but... Oh dear. You have a <i>problem</i> don\'t you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 3, 0, 1, 'I arrived here without an ID and Alex said you could help me...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 3, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 4, 0, 0, 'You aren\'t the first one to wander through here with that particular issue as of late. As it so happens, you\'re in the right place and speaking to the right man... and if you can scratch my back, we\'ll see about relieving that itch on yours too.\\nThere\'s a... particular strongbox being kept in a small shack nearby. I <i>would</i> get it myself, but I only facilitate procurement, not enact. Get me whats in that box and I will help you out.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 5, 0, 1, 'I suppose I don\'t have much choice...', 0, 16, 1, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 5, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 6, 0, 0, 'Did you need something?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 6, 1, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 6, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 7, 0, 0, 'Good to see you again... Did you find Antonio\'s Adaption Factory?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 7, 1, 1, 'I think I have what you were looking for.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 7, 2, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 7, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 8, 0, 0, 'Excellent, I was starting to get worried. I didn\'t want to deal with ICC and their incessant questioning again.\\n\\nLets go ahead and get at least part of your identification issue settled! I\'ll need the Nano Transmitter, the Blank Info Chip, and the Encryption Compiler and ofcourse the Adaptation Factory if you please.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 9, 0, 3, 'Drag and drop the item(s) you want to give to Stanley Goodman into one of the slots available and press "accept"', 4, 10, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 10, 0, 0, 'He pockets the adaptation factory before turning his attention to the three pieces of your future ID chip, plugging them all together.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 10, 1, 0, 'It would seem my instincts were correct about you. You\'re a natural. All it needs now is some additional information and security clearance codes and you should be ready to go. Visit Sarah Greene an \'associate\' of mine, and if you\'re smart you\'d do well to leave out my name. \\nAlso if you haven\'t done so already you should see my good friend Marco Spida and buy a Nanoprogram Container.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 10, 2, 1, 'Thanks, it was fun.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 10, 3, 1, 'I can\'t believe I just did that.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 10, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 11, 0, 0, 'My my... Aren\'t we eager? Ambition is something that is dreadfully lacking from new colonists, but... Oh dear. You have a <i>problem</i> don\'t you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 11, 1, 1, 'I arrived here without an ID and Alex said you could help me...', 0, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 11, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 12, 0, 0, 'No, no you don\'t. Now, I\'ll be uploading the target\'s location to your NCU.\\n\\nThe work itself is relatively simple:\\n1: Buy a lockpick.\\n2: Sneak into the small building undetected. Locate the strongbox your NCU directs you toward and clean it out. Inside you\'ll find an Adaptation Factory.\\n3: Once you\'ve procurred this item, return to me and we\'ll see about creating your unique ID chip.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 13, 0, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 14, 0, 0, 'Excellent, I was starting to get worried. I didn\'t want to deal with ICC and their incessant questioning again.\\n\\nLets go ahead and get at least part of your identification issue settled! I\'ll need the Nano Transmitter, the Blank Info Chip, and the Encryption Compiler and ofcourse the Adaptation Factory if you please.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 14, 1, 3, 'Drag and drop the item(s) you want to give to Stanley Goodman into one of the slots available and press "accept"', 4, 10, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 15, 0, 0, 'I am glad to hear it. As I said, should you ever decide you want slightly more... stable, if not entirely *legal* employment, you know where to find me.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', 15, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Stanley Goodman', -1, 0, 0, 'Watch your back!', 0, 0, 0, 0);
