INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 1, 0, 0, 'A low sigh comes from inside the Peackeeper\'s helmet.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 1, 1, 0, 'Hello citizen, on behalf of the ICC, I welcome you to Rubi-Ka.\\n\\nPlease present your identification to proceed to the elevator.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 2, 0, 1, 'Here\'s my identification.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 2, 1, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 2, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 3, 0, 0, 'Very well then, let\'s see it.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 3, 1, 3, 'Drag and drop the item(s) you want to give to Vaughn Hammond into one of the slots available and press "accept"', 1, 4, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 4, 0, 0, 'Everything...seems to be in order. I have uploaded your identity details to your NCU. You may leave Arete Landing whenever you are ready.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 4, 1, 1, 'How do I leave?', 0, 8, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 5, 0, 0, 'Hello again, citizen. Are you prepared to depart from Arete Landing?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 5, 1, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 5, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 6, 0, 0, 'Let me hear them.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 6, 1, 1, 'What is ICC?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 6, 2, 1, 'Who are you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 6, 3, 1, 'Why do you need an ID to leave this place?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 6, 4, 1, 'What will I find in when I leave Arete Landing?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 6, 5, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 7, 0, 0, 'A low sigh comes from inside the Peackeeper\'s helmet.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 7, 1, 0, 'Hello citizen, on behalf of the ICC, I welcome you to Rubi-Ka.\\n\\nPlease present your identification to proceed to the elevator.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 7, 2, 1, 'Here\'s my identification.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 7, 3, 1, 'I have some questions.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 7, 4, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 8, 0, 0, 'Simply use the elevator.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 8, 1, 1, 'What is ICC?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 8, 2, 1, 'Who are you?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 8, 3, 1, 'Why do you need an ID to leave this place?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 8, 4, 1, 'What will I find in when I leave Arete Landing?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 8, 5, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 9, 0, 0, 'A low sigh comes from inside the Peackeeper\'s helmet.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 10, 0, 0, 'Hello citizen, on behalf of the ICC, I welcome you to Rubi-Ka.\\n\\nPlease present your identification to proceed to the elevator.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 10, 1, 1, 'Here\'s my identification.', 0, 3, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vaughn Hammond', 10, 2, 1, 'I have some questions.', 0, 0, 0, 0);
