INSERT INTO knubotopeners (Playfield, NpcName, Priority, RequireActive, RequireDone, ForbidStarted, Node) VALUES (6553, 'Vaughn Hammond', 110, '1439635506', '', '', 10);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 1, 0, 0, 'You. Take these.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 1, 1, 0, 'His outstretched hand offers you the two objects: One a small pill-sized object with electrical connectors poking from the sides, and the other some fashion of scan and input device. He pulls another object from his pocket with his free hand, a strangely green metallic tube. He waits for you to follow his instructions.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 2, 0, 1, 'Fine, I will hold the items for you.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 2, 1, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 3, 0, 0, 'As you take the two objects in-hand the man begins running his fingers along the tube, pressing at various points on its featureless, smooth surface. As he works a glow begins eminating from within, steadily growing brighter and brighter. After a moment he pauses and looks up to you for the first time, an expectant expression on his face.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 4, 0, 0, '... Well?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 4, 1, 1, '... well what?', 0, 5, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 4, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 5, 0, 0, 'Well get to it!', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 5, 1, 0, 'He seems less than pleased that you haven\'t done... whatever it is he wanted you to do by now.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 5, 2, 0, 'The little thing is an Omni-Tek Technical Library. The scope thing is a Hacker Tool. I want the Library hacked because that will remove that absolutely moronic "Omni-Tek Employee Lock" on the damnable thing. Just use the tool on the library and get back to me when you\'re done.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 5, 3, 0, 'With that he returns his attention to the glowing tube.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 5, 4, 1, 'I\'m done now.', 0, 6, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 5, 5, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 6, 0, 0, 'Are you now...', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 6, 1, 1, 'I was able to hack the device.', 0, 7, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 6, 2, 1, 'On second thought, I need some more time.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 6, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 7, 0, 0, 'Without even blinking an eye the man continues to poke at the tube in his hands, nodding impassively.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 7, 1, 0, 'Very well, leave it here if you would.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 7, 2, 3, 'Drag and drop the item(s) you want to give to Vernon Godfray into one of the slots available and press "accept"', 1, 8, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 8, 0, 0, 'Well then, you seem like you are the useful kind of stray dog. Don\'t tell me, you are here to get my help with an ID card, but I won\'t do it for free. I have a simple task, and you\'ll need that Hacker Tool again. In the dock area, there\'s a Shipping Manifest Terminal. I need that terminal... altered. You can either go in via the freight entrance or the personnel entrance. Either way is up to you. Once you\'re in, find the terminal and use your Hacker Tool on it to reroute some of the data over to one of my... organization\'s own databases. Fairly simple, and once you\'re done I should be able to give you a hand. \\nDo you have any questions?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 8, 1, 1, 'Is this... legal?', 0, 9, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 8, 2, 1, 'Nope.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 8, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 9, 0, 0, 'Technically speaking, no. But neither is getting a fake ID.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 9, 1, 0, 'With that the man nods and returns his attention to the glowing green tube nearby, seemingly forgetting about your presence once more. You suppose question and answer time is over...', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 9, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 10, 0, 0, 'And you finally return. I was starting to think I\'d have to head on over to the docks and fish you out of some trouble.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 10, 1, 1, 'I\'ve returned. The terminal was hacked.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 10, 2, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 11, 0, 0, 'Good. You should have an ID chip of some fashion. Give it here.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 11, 1, 3, 'Drag and drop the item(s) you want to give to Vernon Godfray into one of the slots available and press "accept"', 1, 12, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 12, 0, 0, 'You procure the chip from your pocket, the man quickly snatching it from your grip. He produces his own hacker tool and sets to work, holding the scope end over the small chip as he taps against the interface display. After only a few seconds he nods again and hands it to you once more.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 12, 1, 0, 'There. I\'ve programmed your chip with official ICC clearance codes. Same as if you\'d gotten them from a bureaucrat yourself. You\'ll need that for authentication purposes. Doctor Mason over at the hospital can help you out with imprinting your DNA in to the chip.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 12, 2, 1, 'Great! Anything else?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 12, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 13, 0, 0, 'You. Take these.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 13, 1, 0, 'His outstretched hand offers you the two objects: One a small pill-sized object with electrical connectors poking from the sides, and the other some fashion of scan and input device. He pulls another object from his pocket with his free hand, a strangely green metallic tube. He waits for you to follow his instructions.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 13, 2, 1, 'Fine, I will hold the items for you.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 13, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 14, 0, 0, 'The man\'s head barely even tilts upward as you approach, keeping his focus on the odd objects in his hands.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 14, 1, 0, 'Well?', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 14, 2, 1, 'I was able to hack the device.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 14, 3, 1, 'Goodbye', 0, 0, 2, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 15, 0, 0, 'Without even blinking an eye the man continues to poke at the tube in his hands, nodding impassively.', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 16, 0, 0, 'Very well, leave it here if you would.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 16, 1, 3, 'Drag and drop the item(s) you want to give to Vernon Godfray into one of the slots available and press "accept"', 1, 8, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 17, 0, 0, 'Technically speaking, no. But neither is getting a fake ID.', 0, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 17, 1, 0, 'With that the man nods and returns his attention to the glowing green tube nearby, seemingly forgetting about your presence once more. You suppose question and answer time is over...', 1, 0, 0, 0);
INSERT INTO knubotdialogue (Playfield, NpcName, Node, Ordinal, Kind, Text, Flag, Next, AnswerKind, ActionValue) VALUES (6553, 'Vernon Godfray', 18, 0, 1, 'Goodbye', 0, 0, 2, 0);
